#!/usr/bin/env bash
# Installs a git pre-commit hook that regenerates PROGRESS.md's derived
# sections whenever PROGRESS.md is part of the commit. Run once:
#   bash scripts/install_hook.sh
set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
HOOK="$REPO_ROOT/.git/hooks/pre-commit"

cat > "$HOOK" <<'EOF'
#!/usr/bin/env bash
# Auto-generated by scripts/install_hook.sh
set -euo pipefail
REPO_ROOT="$(git rev-parse --show-toplevel)"

# Only act if PROGRESS.md is staged.
if git diff --cached --name-only | grep -qx "PROGRESS.md"; then
    python3 "$REPO_ROOT/scripts/update_progress.py"
    git add "$REPO_ROOT/PROGRESS.md" "$REPO_ROOT/profile.html"
fi
EOF

chmod +x "$HOOK"
echo "✅ Installed pre-commit hook at $HOOK"
